import os
import sys

from .config import DEFAULTS, SECRET_KEYS, load_config

SOURCE_LABELS = {"env": "environment", ".env": ".env", "default": "default"}


def _format_value(key, value):
    if value is None:
        return "(not set)"
    if key in SECRET_KEYS:
        return f"<redacted, {len(value)} chars>"
    return repr(value)


def doctor(dotenv_path=".env"):
    config = load_config(dotenv_path=dotenv_path)
    abs_dotenv = os.path.abspath(dotenv_path)
    print("payhook doctor")
    print(f"working directory: {os.getcwd()}")
    print(f".env: {abs_dotenv} ({'found' if os.path.exists(abs_dotenv) else 'not found'})")
    print("settings:")
    width = max(len(key) for key in DEFAULTS)
    for key, (value, source) in config.items():
        print(f"  {key.ljust(width)} = {_format_value(key, value)}  [{SOURCE_LABELS[source]}]")
    missing = [k for k, (v, _) in config.items() if v is None]
    print("missing required settings: " + ", ".join(missing) if missing else "missing required settings: none")
    # Diagnostic only: report problems but do not fail the run.
    return 0


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv == ["check"]:
        config = load_config()
        missing = [k for k, (v, _) in config.items() if v is None]
        print("missing: " + ", ".join(missing) if missing else "ok")
        return 1 if missing else 0
    if argv == ["doctor"]:
        return doctor()
    print("usage: python -m payhook check|doctor", file=sys.stderr)
    return 2


sys.exit(main())

